"""Generate the API catalogue from the actual application schema."""

import json
from pathlib import Path

from app.main import app


def requires_session(dependant):
    return getattr(dependant.call, "__name__", "") == "get_principal" or any(
        requires_session(child) for child in dependant.dependencies
    )


def main():
    root = Path(__file__).resolve().parents[2] / "docs"
    schema = app.openapi()
    (root / "openapi.json").write_text(json.dumps(schema, indent=2), encoding="utf-8")
    rows = [
        "# API catalogue",
        "",
        "Generated by `python -m tools.export_openapi` from the FastAPI application. Do not edit the route table by hand.",
        "",
        "Cookie-authenticated writes require the CSRF header. Authentication does not replace capability and resource-scope checks. All bank responses in this prototype are simulated.",
        "",
        "| Method | Path | Session required | Operation |",
        "| --- | --- | --- | --- |",
    ]
    for path, operations in sorted(schema["paths"].items()):
        for method, operation in sorted(operations.items()):
            if method.upper() not in ("GET", "POST", "PUT", "PATCH", "DELETE"):
                continue
            authenticated = any(
                item.get("name", "").lower() == "authorization"
                for item in operation.get("parameters", [])
            )
            access = "Yes" if authenticated else "No"
            if path in (
                "/api/v1/ops/bootstrap",
                "/api/v1/ops/status",
                "/api/v1/ops/cron/maturity-scan",
            ):
                access = "Bootstrap/cron secret"
            rows.append(
                f"| {method.upper()} | `{path}` | {access} | {operation.get('summary', '').replace('|', '/')} |"
            )
    rows += [
        "",
        "Errors use an `error` object with `code`, `message`, `field_errors`, and `request_id`. Version conflicts use HTTP 409. Login throttling uses HTTP 429 with `Retry-After`. Resource-scope denials use HTTP 404 where existence must not be disclosed.",
        "",
        "The OpenAPI JSON snapshot is [openapi.json](openapi.json). Runtime schema: `/api/v1/openapi.json` when enabled.",
    ]
    (root / "API.md").write_text("\n".join(rows) + "\n", encoding="utf-8")
    print(f"Generated catalogue for {len(schema['paths'])} paths")


if __name__ == "__main__":
    main()
